    <script>
        (function() {
            // 1. 数据提取与清洗
            function sanitizeCoT(text) {
                if (!text) return '';
                return text.replace(/^[\s\S]*<\/(?:think|thinking)>/i, '').trim();
            }

            function extractBlocks(text) {
                text = sanitizeCoT(text);
                const blocks = [];
                let currentBlock = "";
                let depth = 0;
                for (let i = 0; i < text.length; i++) {
                    const char = text[i];
                    if (char === '[') {
                        if (depth > 0) currentBlock += char;
                        depth++;
                    } else if (char === ']') {
                        depth--;
                        if (depth === 0) {
                            if (currentBlock.trim()) blocks.push(currentBlock);
                            currentBlock = "";
                        } else if (depth > 0) {
                            currentBlock += char;
                        } else { depth = 0; }
                    } else {
                        if (depth > 0) currentBlock += char;
                    }
                }
                if (depth > 0 && currentBlock.trim()) blocks.push(currentBlock);
                return blocks;
            }

            // 2. 解析原始数据
            const rawData = document.getElementById('liuyu-raw-data').innerText;
            const blocks = extractBlocks(rawData);
            const parsedData = {};

            blocks.forEach(block => {
                const firstPipeIdx = block.indexOf('|');
                if (firstPipeIdx !== -1) {
                    const key = block.substring(0, firstPipeIdx).trim();
                    const value = block.substring(firstPipeIdx + 1).trim();
                    parsedData[key] = value;
                }
            });

            // 3. 昼夜主题判断
            function determineTheme(timeStr) {
                if (!timeStr) return 'day';
                let hour = 12;
                const timeMatch = timeStr.match(/(\d{1,2})[:：]\d{1,2}/);
                if (timeMatch) {
                    hour = parseInt(timeMatch[1], 10);
                    if (/(下午|晚上|夜里)/.test(timeStr) && hour < 12) hour += 12;
                } else {
                    if (/(晚|夜|暗|黑)/.test(timeStr)) return 'night';
                    if (/(早|晨|昼|白|午)/.test(timeStr)) return 'day';
                }
                return (hour >= 6 && hour < 18) ? 'day' : 'night';
            }

            const timeValue = parsedData['Time'] || '';
            const theme = determineTheme(timeValue);
            const container = document.getElementById('mz-main-container');

            if (theme === 'night') {
                container.classList.add('mz-theme-night');
            }

            // 4. 填充数据
            const safeSet = (id, key) => {
                const el = document.getElementById(id);
                if (el) el.innerText = parsedData[key] || '--';
            };

            // 填充极小元数据
            safeSet('mz-date', 'Date');
            safeSet('mz-time', 'Time');
            safeSet('mz-location', 'Location');
            safeSet('mz-weather', 'Weather');

            // 填充弹幕
            const thoughts = parsedData['Thoughts'] || '...';
            // 为了让弹幕连贯，重复拼接几次文本
            document.getElementById('mz-thoughts').innerText = `${thoughts} ✦ ${thoughts} ✦ ${thoughts}`;

            // 填充左列
            safeSet('mz-clothing', 'Clothing');
            safeSet('mz-gaze', 'Gaze');
            safeSet('mz-estrus', 'Estrus');

            // 处理好感度
            const favorStr = parsedData['Favorability'] || '0';
            const numMatch = favorStr.match(/\d+/);
            let percent = 0;
            if (numMatch) {
                percent = Math.min(100, Math.max(0, parseInt(numMatch[0], 10)));
            }
            document.getElementById('mz-favor-num').innerText = favorStr;
            // 延迟一点执行动画
            setTimeout(() => {
                document.getElementById('mz-favor-fill').style.width = percent + '%';
            }, 100);

            // 填充右列
            safeSet('mz-anecdote', 'Anecdote');

            // 处理两个计划 (解析 "1. xxx 2. xxx" 格式)
            const planStr = parsedData['Plan'] || '';
            const planContainer = document.getElementById('mz-plan');

            // 尝试用正则拆分 "1. " 和 "2. "
            const planRegex = /1\.\s*(.*?)\s*2\.\s*(.*)/;
            const planMatch = planStr.match(planRegex);

            if (planMatch && planMatch.length >= 3) {
                planContainer.innerHTML = `
                    <div class="mz-plan-item"><strong>01.</strong> ${planMatch[1]}</div>
                    <div class="mz-plan-item"><strong>02.</strong> ${planMatch[2]}</div>
                `;
            } else {
                // 如果AI没有严格遵守格式，直接输出
                planContainer.innerHTML = `<div class="mz-plan-item">${planStr}</div>`;
            }

        })();
    </script>
